function hideSceneMenu(){$('#scene-menu').hidden=true;}
function sceneMenu(event,id){event.preventDefault();if(admin()&&selectedScenes.has(id)&&selectedScenes.size>1)return bulkSceneMenu(event);const scene=state.show.scenes.find(s=>s.id===id),menu=$('#scene-menu');menu.replaceChildren();const add=(name,run)=>{const b=button(name,async()=>{hideSceneMenu();await run();});b.setAttribute('role','menuitem');menu.append(b);};add('Run scene',()=>playScene(id));if(admin()){add('Edit scene',()=>edit(id));add('MIDI trigger',()=>mapping(id));add('Move to folder',()=>modal('Move scene','<label>Folder<select id="move-folder">'+options(state.show.folders,scene.page)+'</select></label>',[button('Cancel',close),button('Move',async()=>{await cmd('moveScene',{id,folder:$('#move-folder').value});await close();})]));add('Duplicate scene',()=>cmd('duplicate',{id}));add('Delete scene',async()=>{if(confirm('Delete '+scene.name+'?'))await cmd('deleteScene',{id});});}menu.hidden=false;menu.style.left=Math.max(8,Math.min(event.clientX,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(8,Math.min(event.clientY,innerHeight-menu.offsetHeight-8))+'px';menu.querySelector('button')?.focus();}
