async function flushManual(){if(manualBusy)return;manualBusy=true;try{while(manualQueue.size){const changes=[...manualQueue.values()];manualQueue.clear();await cmd('manualBatch',{changes});}}catch(e){manualQueue.clear();fail(e);}finally{manualBusy=false;}}
function manualLight(id){const f=state.show.fixtures.find(f=>f.id===id),controls=commonControls(state.show,[id]);modal('Manual controls · '+f.name,'<p>Changes stay through scene and MIDI changes until saved or released.</p>'+controlHTML(controls,state.engine.captureFrame,'manual'),[button('Done',close)]);$('#dialog-body').querySelectorAll('[data-shared]').forEach(x=>x.oninput=()=>{const c=controls[Number(x.dataset.shared)],value=Number(x.value);$('#manual-value-'+x.dataset.shared).value=value+(c.percent?'%':'');for(const change of controlChanges(c,value))manualQueue.set(id+':'+(change.offset??'brightness'),change);flushManual();});wirePalette($('#dialog-body'),controls,state.engine.captureFrame,queueManual);}
