  wirePhoto(false,draw,$('#dialog-body'),selection);$('#capture-folder').onchange=e=>{browseFolder=e.target.value;draw();};$('#new-capture-scene').onclick=()=>{newScene=!(newScene&&newSceneFolder===browseFolder);newSceneFolder=browseFolder;if(newScene)state.show.fixtures.filter(f=>f.universe===1).forEach(f=>selection.add(f.id));else selection.clear();draw();};$('#capture-name')?.addEventListener('input',e=>name=e.target.value);$('#save-select-none').onclick=()=>{selection.clear();draw();};$('#dialog-body').querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{const id=b.dataset.destination;if(destinations.has(id))destinations.delete(id);else destinations.add(id);draw();});
