function calibrateMovement(id){
 const fixture=state.show.fixtures.find(f=>f.id===id),controls=controlsFor(state.show,id),pan=controls.find(c=>c.role==='pan'),tilt=controls.find(c=>c.role==='tilt');if(!pan||!tilt)throw Error('This fixture has no verified pan/tilt channels');if(!active())throw Error('Connect to identify movement on site');const read=c=>((state.engine.channelFrame[c.address]??0)*(c.pair?256:1)+(c.pair?(state.engine.channelFrame[c.address+1]??0):0))/c.max;let point=[read(pan),read(tilt)],points=structuredClone(fixture.movement?.points??{});
 const draw=()=>{modal('Teach movement · '+fixture.name,'<p>Use this raw movement pad to aim the light. Record Centre, then the positions that look Left, Right, Up and Down on your stage. The directions may be angled or skewed.</p><div class="calibration-desk"><div class="raw-movement movement-pad" tabindex="0" role="group" aria-label="Raw pan tilt teaching pad"><i></i></div><div>'+['centre','left','right','up','down'].map(key=>'<button data-record-direction="'+key+'">Record '+key+(points[key]?' ✓':'')+'</button>').join('')+'</div></div>',[button('Cancel',close),button('Save directions',async()=>{await settleManual();await cmd('setMovement',{id,points});await close();},'primary')]);const pad=$('.raw-movement'),paint=()=>{pad.querySelector('i').style.left=point[0]*100+'%';pad.querySelector('i').style.top=point[1]*100+'%';};paint();const move=e=>{const r=pad.getBoundingClientRect();point=[Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];paint();queueManual([pan,tilt].map((c,i)=>({fixtureId:id,offset:c.offset,value:Math.round(point[i]*c.max)})));};pad.onpointerdown=e=>{if(e.button!==0)return;pad.setPointerCapture(e.pointerId);move(e);};pad.onpointermove=e=>{if(pad.hasPointerCapture(e.pointerId))move(e);};pad.onpointerup=e=>{if(pad.hasPointerCapture(e.pointerId))pad.releasePointerCapture(e.pointerId);};document.querySelectorAll('[data-record-direction]').forEach(b=>b.onclick=async()=>{await settleManual();points[b.dataset.recordDirection]=point.slice();draw();});};draw();
}

