function patchHTML(){const occupied=state.show.fixtures.filter(f=>f.universe===1).reduce((n,f)=>n+f.width,0);return '<section class="patch-overview"><h3>Universe 1 · DMX patch</h3><p class="small">'+occupied+' / 512 channels patched · click a channel to edit its light</p><div class="dmx-patch">'+Array.from({length:512},(_,i)=>{const f=state.show.fixtures.find(f=>f.universe===1&&i>=f.address-1&&i<f.address-1+f.width),p=f&&state.show.profiles.find(p=>p.id===f.profileId),label=f?f.name+' · '+(p.channels[i-f.address+1]?.name??p.channels[i-f.address+1]?.role??'Channel'): 'Unpatched';return '<button '+(f?'data-patch-fixture="'+f.id+'" style="--patch-hue:'+((state.show.fixtures.indexOf(f)*47)%360)+'"':'disabled')+' title="'+(i+1)+' · '+esc(label)+'" aria-label="DMX '+(i+1)+' '+esc(label)+'">'+(i+1)+'</button>';}).join('')+'</div></section>';}

