function channelEditor(id){const f=state.show.fixtures.find(f=>f.id===id),profile=state.show.profiles.find(p=>p.id===f.profileId),controls=controlsFor(state.show,id);modal('DMX channels · '+f.name,'<p>Channel settings before the global dimmer and 11am mute. Function/reset channels are shown read-only.</p><div class="raw-channels">'+profile.channels.map((c,offset)=>{const control=controls.find(x=>!x.virtual&&x.offset===offset),value=control?((state.engine.channelFrame[control.address]??0)*(control.pair?256:1)+(control.pair?(state.engine.channelFrame[control.address+1]??0):0)):state.engine.channelFrame[f.address-1+offset];return '<div class="channel-row"><span>CH '+(f.address+offset)+'</span><strong>'+esc(c.name??c.role)+'</strong>'+(control?'<input type="range" data-raw-channel="'+offset+'" min="0" max="'+control.max+'" value="'+value+'" '+(!active()?'disabled':'')+'><output data-raw-value="'+offset+'">'+value+'</output>':'<span class="small">'+(c.fine?'Fine channel':'Read only')+'</span><output>'+value+'</output>')+'<small>Output <output data-live-channel="'+(f.address-1+offset)+'">'+state.engine.frame[f.address-1+offset]+'</output></small></div>';}).join('')+'</div>',[button('Done',close)]);document.querySelectorAll('[data-raw-channel]').forEach(input=>input.oninput=()=>{const offset=Number(input.dataset.rawChannel),value=Number(input.value);document.querySelector('[data-raw-value="'+offset+'"]').value=value;queueManual([{fixtureId:id,offset,value}]);});}

